/**
 * Handle video streaming from R2 bucket
 */
async function handleVideoStream(request, env, pathname) {
  const videoFilename = pathname.replace('/videos/', '');
  
  if (!videoFilename) {
    return new Response(JSON.stringify({ 
      error: 'Bad Request',
      message: 'Video filename is required'
    }), {
      status: 400,
      headers: {
        'Content-Type': 'application/json',
        ...CORS_HEADERS
      }
    });
  }

  try {
    // Get video object from R2 bucket
    const object = await env.VIDEOS_BUCKET.get(videoFilename);
    
    if (!object) {
      return new Response(JSON.stringify({ 
        error: 'Not Found',
        message: `Video ${videoFilename} not found`
      }), {
        status: 404,
        headers: {
          'Content-Type': 'application/json',
          ...CORS_HEADERS
        }
      });
    }

    // Handle range requests for video seeking
    const range = request.headers.get('Range');
    const objectSize = object.size;
    
    if (range) {
      const parts = range.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0], 10);
      const end = parts[1] ? parseInt(parts[1], 10) : objectSize - 1;
      const chunkSize = (end - start) + 1;
      
      // Get the range from R2
      const rangeObject = await env.VIDEOS_BUCKET.get(videoFilename, {
        range: { offset: start, length: chunkSize }
      });
      
      if (!rangeObject) {
        return new Response('Range Not Satisfiable', { status: 416 });
      }
      
      return new Response(rangeObject.body, {
        status: 206,
        headers: {
          'Content-Type': 'video/mp4',
          'Content-Length': chunkSize.toString(),
          'Content-Range': `bytes ${start}-${end}/${objectSize}`,
          'Accept-Ranges': 'bytes',
          'Cache-Control': 'public, max-age=31536000',
          ...CORS_HEADERS
        }
      });
    }
    
    // Return full video for non-range requests
    return new Response(object.body, {
      headers: {
        'Content-Type': 'video/mp4',
        'Content-Length': objectSize.toString(),
        'Accept-Ranges': 'bytes',
        'Cache-Control': 'public, max-age=31536000',
        ...CORS_HEADERS
      }
    });
    
  } catch (error) {
    console.error('Video streaming error:', error);
    return new Response(JSON.stringify({ 
      error: 'Internal Server Error',
      message: 'Failed to stream video'
    }), {
      status: 500,
      headers: {
        'Content-Type': 'application/json',
        ...CORS_HEADERS
      }
    });
  }
}

/**
 * Handle static asset requests
 */
async function handleStaticAsset(request, pathname) {
  // Remove leading slash for asset lookup
  const assetPath = pathname.slice(1);
  
  if (STATIC_ASSETS[assetPath]) {
    const asset = STATIC_ASSETS[assetPath];
    
    // Determine content type
    const contentType = getContentType(assetPath);
    
    return new Response(asset.content, {
      headers: {
        'Content-Type': contentType,
        'Cache-Control': 'public, max-age=31536000',
        ...CORS_HEADERS
      }
    });
  }

  // Handle root path
  if (pathname === '/') {
    const indexAsset = STATIC_ASSETS['index.html'];
    if (indexAsset) {
      return new Response(indexAsset.content, {
        headers: {
          'Content-Type': 'text/html',
          ...CORS_HEADERS
        }
      });
    }
  }

  // SPA fallback - serve index.html for all other routes
  const indexAsset = STATIC_ASSETS['index.html'];
  if (indexAsset) {
    return new Response(indexAsset.content, {
      headers: {
        'Content-Type': 'text/html',
        ...CORS_HEADERS
      }
    });
  }

  // Fallback response
  return new Response('Not Found', {
    status: 404,
    headers: CORS_HEADERS
  });
}

/**
 * Get content type based on file extension
 */
function getContentType(path) {
  const ext = path.split('.').pop()?.toLowerCase();
  
  const mimeTypes = {
    'html': 'text/html',
    'css': 'text/css',
    'js': 'application/javascript',
    'json': 'application/json',
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'ico': 'image/x-icon',
    'woff': 'font/woff',
    'woff2': 'font/woff2',
    'ttf': 'font/ttf',
    'eot': 'application/vnd.ms-fontobject'
  };

  return mimeTypes[ext] || 'application/octet-stream';
}

/**
 * Generate mock timeline data for testing
 */
function generateMockTimeline(duration) {
  const timeline = [];
  const fps = 30;
  const totalFrames = Math.floor(duration * fps);
  
  for (let frame = 0; frame < totalFrames; frame += 150) { // Every 5 seconds
    const timestamp = frame / fps;
    const contestants = [];
    
    // Randomly add contestants with varying confidence
    if (Math.random() > 0.7) {
      const numFaces = Math.floor(Math.random() * 3) + 1;
      for (let i = 0; i < numFaces; i++) {
        // Use real contestant data from global CONTESTANT_DATA
        const randomContestantId = Math.floor(Math.random() * 96) + 1;
        const realContestant = CONTESTANT_DATA.find(c => c.id === randomContestantId);
        
        contestants.push({
          id: `face_${frame}_${i}`,
          contestant_id: randomContestantId,
          contestant_name: realContestant ? realContestant.name : '未知',
          contestant_nickname: realContestant ? realContestant.nickname : '未知',
          confidence: 0.6 + Math.random() * 0.4,
          bounding_box: {
            x: Math.random() * 300 + 50,
            y: Math.random() * 200 + 50, 
            width: 120 + Math.random() * 80,
            height: 150 + Math.random() * 100
          },
          timestamp: timestamp,
          interpolated: false
        });
      }
    }
    
    timeline.push({
      frame_number: frame,
      timestamp: timestamp,
      contestants: contestants
    });
  }
  
  return timeline;
}